package com.collabspace.controller; import com.collabspace.dto.MessageDtos.*; import com.collabspace.service.MessageService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequiredArgsConstructor public class MessageController {private final MessageService s; @GetMapping("/api/channels/{channelId}/messages") public Page<MessageResponse> history(@PathVariable UUID channelId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return s.history(channelId,page,size);}@PutMapping("/api/messages/{id}") public MessageResponse edit(@PathVariable UUID id,@Valid @RequestBody SendMessageRequest r){return s.edit(id,r.content());}@DeleteMapping("/api/messages/{id}") public void delete(@PathVariable UUID id){s.delete(id);}@PostMapping("/api/messages/{id}/reactions") public void react(@PathVariable UUID id,@Valid @RequestBody ReactionRequest r){s.react(id,r.emoji());}@GetMapping("/api/messages/search") public Page<MessageResponse> search(@RequestParam UUID workspaceId,@RequestParam String q,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return s.search(workspaceId,q,page,size);}}